-- =====================================================================
-- Student Voice Portal - Migration v3: student accounts, OTP, complaint limit
-- Run AFTER schema.sql (v2). Target: MySQL 8.0.16+ or MariaDB 10.4+.
-- SAFE TO RE-RUN: every step checks whether it was already applied.
--
-- New features covered here (database part only):
--   1. Student login     : student.email + bcrypt password_hash (default
--                          password generated by the team, changed at first login)
--   2. OTP on submission : complaint_otp table (6-digit code, stored as a hash,
--                          5-minute expiry, max 3 attempts, single use)
--   3. Complaint limit   : an identified student may have at most 2 OPEN
--                          complaints (Received / Under Review). A third one is
--                          allowed only after an earlier one is Resolved or Rejected.
--   (QR code, Google Calendar and pausing anonymous complaints need no DB change.)
--
-- Security notes for the API team:
--   * Login always checks email AND password together; never look a student
--     up by password. Passwords are not required to be "unique" - random
--     generated passwords make collisions practically impossible.
--   * Never store a plain password or a plain OTP. password_hash = bcrypt,
--     code_hash = SHA-256 of (code + server secret).
--   * Anonymous complaints must never be linked to a logged-in student.
-- =====================================================================

USE student_voice_portal;

-- ---------------------------------------------------------------------
-- Helper: add a column only if it does not exist yet (keeps this re-runnable)
-- ---------------------------------------------------------------------
DROP PROCEDURE IF EXISTS svp_add_column;
DROP PROCEDURE IF EXISTS svp_add_constraint;
DELIMITER $$
CREATE PROCEDURE svp_add_column(IN p_table VARCHAR(64), IN p_column VARCHAR(64), IN p_definition TEXT)
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS
                 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = p_column) THEN
    SET @svp_sql = CONCAT('ALTER TABLE ', p_table, ' ADD COLUMN ', p_column, ' ', p_definition);
    PREPARE svp_stmt FROM @svp_sql;
    EXECUTE svp_stmt;
    DEALLOCATE PREPARE svp_stmt;
  END IF;
END$$

CREATE PROCEDURE svp_add_constraint(IN p_table VARCHAR(64), IN p_name VARCHAR(64), IN p_definition TEXT)
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.TABLE_CONSTRAINTS
                 WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND CONSTRAINT_NAME = p_name) THEN
    SET @svp_sql = CONCAT('ALTER TABLE ', p_table, ' ADD CONSTRAINT ', p_name, ' ', p_definition);
    PREPARE svp_stmt FROM @svp_sql;
    EXECUTE svp_stmt;
    DEALLOCATE PREPARE svp_stmt;
  END IF;
END$$
DELIMITER ;

-- ---------------------------------------------------------------------
-- 1. Student login columns
-- ---------------------------------------------------------------------
-- email is NULL for old sample students who have no account yet; they simply
-- cannot log in. Every imported student gets an email and a password_hash.
CALL svp_add_column('student', 'email',                 'VARCHAR(150) NULL AFTER registration_no');
CALL svp_add_column('student', 'password_hash',         'CHAR(60) CHARACTER SET ascii COLLATE ascii_bin NULL AFTER email');
CALL svp_add_column('student', 'must_change_password',  'BOOLEAN NOT NULL DEFAULT TRUE AFTER password_hash');
CALL svp_add_column('student', 'failed_login_attempts', 'TINYINT UNSIGNED NOT NULL DEFAULT 0 AFTER must_change_password');
CALL svp_add_column('student', 'locked_until',          'DATETIME NULL AFTER failed_login_attempts');
CALL svp_add_column('student', 'last_login_at',         'DATETIME NULL AFTER locked_until');
CALL svp_add_column('student', 'is_active',             'BOOLEAN NOT NULL DEFAULT TRUE AFTER last_login_at');

-- One account per email (case-insensitive because of the unicode_ci collation).
CALL svp_add_constraint('student', 'uq_student_email',    'UNIQUE (email)');
-- Emails are stored in lower case so "Ali@Uni.edu" and "ali@uni.edu" are the same account.
CALL svp_add_constraint('student', 'chk_student_email',
  'CHECK (email IS NULL OR (CAST(email AS BINARY) = CAST(LOWER(email) AS BINARY) AND email REGEXP ''^[^@ ]+@[^@ ]+[.][^@ ]+$''))');
-- A bcrypt hash is always 60 characters and starts with $2a$, $2b$ or $2y$.
CALL svp_add_constraint('student', 'chk_student_pw_hash',
  'CHECK (password_hash IS NULL OR password_hash REGEXP ''^[$]2[aby][$][0-9]{2}[$].{53}$'')');
-- An account that can log in must have both an email and a password.
CALL svp_add_constraint('student', 'chk_student_account',
  'CHECK ((email IS NULL AND password_hash IS NULL) OR (email IS NOT NULL AND password_hash IS NOT NULL))');

-- ---------------------------------------------------------------------
-- 2. OTP sent to the student's email before an identified complaint is accepted
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS complaint_otp (
  otp_id      INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  student_id  INT UNSIGNED  NOT NULL,
  code_hash   CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,  -- SHA-256 hex, never the plain code
  attempts    TINYINT UNSIGNED NOT NULL DEFAULT 0,                      -- wrong guesses so far
  created_at  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at  DATETIME      NOT NULL,                                   -- created_at + 5 minutes (set by API)
  used_at     DATETIME      NULL,                                       -- set once, when the complaint is accepted
  CONSTRAINT pk_complaint_otp      PRIMARY KEY (otp_id),
  CONSTRAINT chk_otp_code_hash     CHECK (code_hash REGEXP '^[0-9a-f]{64}$'),
  CONSTRAINT chk_otp_attempts      CHECK (attempts <= 3),
  CONSTRAINT chk_otp_expiry        CHECK (expires_at > created_at),
  CONSTRAINT fk_otp_student        FOREIGN KEY (student_id) REFERENCES student (student_id),
  INDEX ix_otp_student_created     (student_id, created_at)
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- 3. Limit: at most 2 open identified complaints per student
-- ---------------------------------------------------------------------
-- The API must ALSO lock the student row first, inside the same transaction:
--   SELECT student_id FROM student WHERE student_id = ? FOR UPDATE;
-- so two quick submissions cannot both pass the check. The trigger is the
-- database's own safety net and returns a clear error code for the API to map to 409.
DROP TRIGGER IF EXISTS trg_complaint_bi_open_limit;
DELIMITER $$
CREATE TRIGGER trg_complaint_bi_open_limit BEFORE INSERT ON complaint
FOR EACH ROW FOLLOWS trg_complaint_bi
BEGIN
  IF NEW.mode = 'Identified' AND
     (SELECT COUNT(*) FROM complaint
       WHERE student_id = NEW.student_id
         AND status IN ('Received', 'Under Review')) >= 2 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'OPEN_COMPLAINT_LIMIT: a student may have at most 2 open complaints';
  END IF;
END$$
DELIMITER ;

-- Helper view for the API and the student's "My complaints" message.
CREATE OR REPLACE VIEW v_student_open_complaints AS
  SELECT s.student_id,
         s.email,
         COUNT(c.complaint_id) AS open_complaints
    FROM student s
    LEFT JOIN complaint c
      ON c.student_id = s.student_id
     AND c.status IN ('Received', 'Under Review')
   GROUP BY s.student_id, s.email;

-- Clean up the helpers
DROP PROCEDURE IF EXISTS svp_add_column;
DROP PROCEDURE IF EXISTS svp_add_constraint;

SELECT 'Migration v3 applied: student accounts, complaint_otp, open-complaint limit' AS result;